const RevenueNoticeModal=function(n){const t={initialize:function(){t.showDialog();t.initEvent()},initEvent:function(){n("#closeModal").on("click",function(){t.hideDialog()});n(".modal-redirect-revenue").on("click",function(){t.hideDialog();Site.redirect(Site.resolveRelativeUrl("RevenueSharingStructure"))})},showDialog:function(){const t=sessionStorage.getItem("isShowedRevenueNoticeModal");t||n("#revenueNoticeModal").modal({backdrop:"static",keyboard:!1})},hideDialog:function(){sessionStorage.setItem("isShowedRevenueNoticeModal","true");n("#revenueNoticeModal").modal("hide")}};return t}(jQuery);RevenueNoticeModal.initialize();